args.content:
$ErrorActionPreference = 'SilentlyContinue'

Write-Output '=== nvJPEG DLL search ==='

$roots = @(
  'C:\Program Files\NVIDIA GPU Computing Toolkit',
  'C:\Program Files\NVIDIA Corporation',
  'C:\Program Files\NVIDIA',
  'C:\ProgramData\NVIDIA',
  'C:\Windows\System32',
  'C:\Windows\SysWOW64',
  'C:\Program Files\Python312',
  'C:\Program Files\Python311',
  'C:\Python312',
  'C:\ProgramData\anaconda3',
  'C:\ProgramData\miniconda3'
)

foreach ($r in $roots) {
  if (Test-Path -LiteralPath $r) {
    Get-ChildItem -LiteralPath $r -Recurse -Filter 'nvjpeg*.dll' -File |
      ForEach-Object {
        Write-Output ('{0}|{1}|{2}|{3}' -f $_.FullName, $_.Length, $_.VersionInfo.FileVersion, $_.LastWriteTime.ToString('yyyy-MM-dd'))
      }
  }
}

Write-Output '=== CUDA toolkit versions present ==='
$cuda = 'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA'
if (Test-Path -LiteralPath $cuda) {
  Get-ChildItem -LiteralPath $cuda -Directory | ForEach-Object { Write-Output $_.FullName }
}

Write-Output '=== NVJPEG env vars ==='
Get-ChildItem Env: | Where-Object { $_.Name -match 'CUDA|NVJPEG|NVIDIA' } | ForEach-Object { Write-Output ('{0}={1}' -f $_.Name, $_.Value) }

Write-Output '=== nvcc / cuda headers ==='
$hdr = Get-ChildItem -LiteralPath $cuda -Recurse -Filter 'nvjpeg.h' -File | ForEach-Object { $_.FullName }
if ($hdr) { $hdr | ForEach-Object { Write-Output $_ } } else { Write-Output 'nvjpeg.h NOT FOUND' }

import json, sys, urllib.request

URLS = [
    'https://services.nvd.nist.gov/rest/json/cves/2.0?cveId=CVE-2026-65160',
]

out = {}
for u in URLS:
    try:
        req = urllib.request.Request(u, headers={'User-Agent': 'curl/8'})
        with urllib.request.urlopen(req, timeout=60) as r:
            body = r.read().decode('utf-8', 'replace')
        out[u] = json.loads(body)
    except Exception as e:
        out[u] = {'ERROR': repr(e)}

with open('cve_65160_nvd.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

for u, d in out.items():
    print('=== URL', u)
    if 'ERROR' in d:
        print('ERROR', d['ERROR'])
        continue
    for v in d.get('vulnerabilities', []):
        c = v['cve']
        print('id:', c.get('id'))
        print('published:', c.get('published'), 'lastModified:', c.get('lastModified'))
        print('status:', c.get('vulnStatus'))
        print('source:', c.get('sourceIdentifier'))
        for desc in c.get('descriptions', []):
            print('desc[%s]: %s' % (desc.get('lang'), desc.get('value')))
        for w in c.get('weaknesses', []):
            print('weakness:', w.get('source'), [ (dd.get('value'), dd.get('description')) for dd in w.get('description', []) ])
        for m in c.get('metrics', {}):
            print('metrics key:', m)
            for e in c.get('metrics')[m]:
                print('   ', json.dumps(e, ensure_ascii=False))
        for ref in c.get('references', []):
            print('ref:', ref.get('url'), ref.get('tags'))
        print('configurations:', json.dumps(c.get('configurations', []), ensure_ascii=False)[:2000])
